   325	                                               "PKIX1.pkcs-12-SecretBag",
   326	                                               &c2)) != ASN1_SUCCESS) {
   327	                        gnutls_assert();
   328	                        ret = _gnutls_asn2err(ret);
   329	                        goto cleanup;
   330	                }
   331	
   332	                ret =
   333	                    asn1_write_value(c2, "secretTypeId", RANDOM_NONCE_OID,
   334	                                     1);
   335	                if (ret != ASN1_SUCCESS) {
   336	                        gnutls_assert();
   337	                        ret = _gnutls_asn2err(ret);
   338	                        goto cleanup;
   339	                }
   340	
   341	                ret =
   342	                    _gnutls_x509_write_string(c2, "secretValue", raw,
   343	                                              ASN1_ETYPE_OCTET_STRING);
   344	                if (ret < 0) {
   345	                        gnutls_assert();
   346	                        goto cleanup;
   347	                }
   348	                break;
   349	
   350	        default:
   351	                gnutls_assert();
   352	                asn1_delete_structure(&c2);
   353	                return GNUTLS_E_UNIMPLEMENTED_FEATURE;
   354	        }
   355	
   356	        ret = _gnutls_x509_der_encode(c2, "", out, 0);
   357	
   358	        if (ret < 0) {
   359	                gnutls_assert();
   360	                goto cleanup;
   361	        }
   362	
   363	        asn1_delete_structure(&c2);
   364	
   365	        return 0;
   366	
   367	
   368	      cleanup:
